/* -------------------------------------------------------------------------- */
/* Deterministic UUIDs (so re-seeding keeps the same ids)                     */
/* -------------------------------------------------------------------------- */
function fnv(str: string, seed: number): number {
  let h = 0x811c9dc5 ^ seed;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}
export function stableId(key: string): string {
  const hex = [1, 2, 3, 4].map((s) => fnv(key, s * 0x9e3779b1).toString(16).padStart(8, "0")).join("");
  // format as RFC 4122 v4-looking uuid
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-4${hex.slice(13, 16)}-a${hex.slice(17, 20)}-${hex.slice(20, 32)}`;
}

export const slugify = (v: string) =>
  v
    .toLowerCase()
    .replace(/['’]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");

