/* -------------------------------------------------------------------------- */
const tax = (name: string, sort: number, description: string, image: string | null): Taxonomy => ({
  id: stableId(`tax:${name}`),
  name,
  slug: slugify(name),
  description,
  image_url: image,
  sort_order: sort,
  is_visible: true,
  seo_title: null,
  seo_description: null,
});

