/* -------------------------------------------------------------------------- */
/* Expanded catalogue (rows exactly as they are stored in the database)       */
/* -------------------------------------------------------------------------- */

export interface BuiltCatalog {
  products: Product[];
  variants: ProductVariant[];
  images: ProductImage[];
  productStyles: { product_id: string; style_id: string }[];
  charms: Charm[];
  reviews: Review[];
  shapes: Record<string, BagShape>;
}

let built: BuiltCatalog | null = null;

export function buildCatalog(): BuiltCatalog {
  if (built) return built;
  const products: Product[] = [];
  const variants: ProductVariant[] = [];
  const images: ProductImage[] = [];
  const productStyles: { product_id: string; style_id: string }[] = [];
  const shapes: Record<string, BagShape> = {};
  const baseDate = Date.parse("2026-11-01T06:00:00.000Z");

  seedProducts.forEach((sp, index) => {
    const slug = productSlug(sp.name);
    const id = stableId(`product:${slug}`);
    shapes[slug] = sp.shape;
    const category = categories.find((c) => c.name === sp.category)!;
    const collection = collections.find((c) => c.name === sp.collection)!;
    const created = new Date(baseDate - (sp.flags?.isNew ? index : 40 + index) * 86_400_000).toISOString();
    products.push({
      id,
      name: sp.name,
      slug,
      short_description: sp.short,
      description: sp.description,
      category_id: category.id,
      collection_id: collection.id,
      material: sp.material,
      dimensions: `${sp.dims.w} × ${sp.dims.h} × ${sp.dims.d} cm`,
      width_cm: sp.dims.w,
      height_cm: sp.dims.h,
      depth_cm: sp.dims.d,
      strap_drop_cm: sp.dims.strap ?? null,
      weight_g: sp.weight_g,
      care_instructions: CARE_DEFAULT,
      price: sp.price,
      compare_at_price: sp.compare_at_price ?? null,
      cost_price: sp.cost_price,
      gst_rate: sp.gst_rate ?? 18,
      status: "published",
      publish_at: null,
      is_featured: !!sp.flags?.featured,
      is_trending: !!sp.flags?.trending,
      is_new: !!sp.flags?.isNew,
      has_spin: !!sp.spin,
      low_stock_threshold: 5,
      seo_title: null,
      seo_description: null,
      rating_avg: sp.rating.avg,
      rating_count: sp.rating.count,
      total_sold: sp.sold,
      sort_order: index + 1,
      created_at: created,
    });
    sp.styles.forEach((s) => {
      productStyles.push({ product_id: id, style_id: styles.find((x) => x.name === s)!.id });
    });
    sp.colours.forEach((c, ci) => {
      const vid = stableId(`variant:${slug}:${c.name}`);
      const code = slug
        .replace(/^the-/, "")
        .split("-")
        .map((w) => w.slice(0, 3))
        .join("")
        .toUpperCase();
      variants.push({
        id: vid,
        product_id: id,
        colour_name: c.name,
        colour_hex: COLOURS[c.name],
        sku: `SC-${code}-${colourSlug(c.name).replace(/-/g, "").slice(0, 4).toUpperCase()}`,
        stock: c.stock,
        price_override: null,
        is_default: ci === 0,
        sort_order: ci,
      });
      const views: ("front" | "angle" | "detail")[] = ci === 0 ? ["front", "angle", "detail"] : ["front", "angle"];
      views.forEach((view, vi) => {
        images.push({
          id: stableId(`image:${slug}:${c.name}:${view}`),
          product_id: id,
          variant_id: vid,
          url: productImagePath(slug, c.name, view),
          alt: `${sp.name} in ${c.name.toLowerCase()} leather — ${view === "front" ? "front view" : view === "angle" ? "three-quarter view" : "close-up of the stitching"}`,
          kind: "gallery",
          sort_order: vi,
          is_primary: ci === 0 && vi === 0,
          width: 1000,
          height: 1250,
        });
      });
    });
    if (sp.spin) {
      for (let f = 0; f < SPIN_FRAMES; f++) {
        images.push({
          id: stableId(`spin:${slug}:${f}`),
          product_id: id,
          variant_id: null,
          url: spinFramePath(slug, f),
          alt: `${sp.name} 360° view, frame ${f + 1}`,
          kind: "spin",
          sort_order: f,
          is_primary: false,
          width: 1000,
          height: 1000,
        });
      }
    }
  });

  const charms: Charm[] = seedCharms.map((c) => ({
    id: c.id,
    name: c.name,
    slug: c.slug,
    description: c.description,
    price: c.price,
    image_url: c.image_url,
    stock: c.stock,
    is_active: true,
    sort_order: c.sort_order,
  }));

  const reviews: Review[] = seedReviews.map((r, i) => ({
    id: stableId(`review:${i}`),
    product_id: products.find((p) => p.name === r.product)!.id,
    author_name: r.author,
    rating: r.rating,
    title: r.title,
    body: r.body,
    images: [],
    status: "approved",
    is_verified: true,
    admin_reply: i === 2 ? "Thank you, Meera! The leather softens a little with use, which makes it feel lighter on the shoulder." : null,
    created_at: new Date(baseDate - (i + 2) * 3 * 86_400_000).toISOString(),
  }));

  built = { products, variants, images, productStyles, charms, reviews, shapes };
  return built;
}
